using System;using System.IO;using System.Linq;using System.Threading;using System.Threading.Tasks;using System.Collections.Generic;
namespace ServiceTool { internal static class CloudLiveTests {
[STAThread]static int Main(){try{Run();return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
static void Run(){var token=CancellationToken.None;var source=new BundleCloudSource();string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"downloads");Directory.CreateDirectory(root);var files=source.Scan(BundleCloud.Yandex,token,Console.WriteLine).Where(f=>f.Group!="Программы").ToList();Console.WriteLine("YANDEX FILES="+files.Count);var errors=new System.Collections.Concurrent.ConcurrentBag<BundleRemoteFile>();int done=0;
Parallel.ForEach(files,new ParallelOptions{MaxDegreeOfParallelism=3},f=>{try{if(!BundlePublication.Matches(root,f,token))source.Transfer(BundleCloud.Yandex).Download(f,root,null,x=>{},token);if(!BundlePublication.Matches(root,f,token))throw new Exception("hash mismatch");Console.WriteLine("OK "+Interlocked.Increment(ref done)+" "+f.Size+" "+f.Path);}catch(Exception e){errors.Add(f);Console.WriteLine("YANDEX FAILED "+f.Path+" "+e.Message);}});
var pending=errors.ToList();bool simulated=pending.Count==0;if(simulated){pending=new List<BundleRemoteFile>{files.Where(f=>f.Size>0).OrderBy(f=>f.Size).First(),files.OrderByDescending(f=>f.Size).First()};foreach(var f in pending){string local=YandexBundleSource.LocalPath(root,f.Path),part=BundleTransfer.PartPath(root,f);Directory.CreateDirectory(Path.GetDirectoryName(part));using(var input=File.OpenRead(local))using(var output=File.Create(part)){byte[] b=new byte[65536];long left=Math.Max(1,f.Size/3);while(left>0){int n=input.Read(b,0,(int)Math.Min(left,b.Length));if(n==0)break;output.Write(b,0,n);left-=n;}}File.Move(local,local+".test-original");}Console.WriteLine("SIMULATED TWO INCOMPLETE FILES");}
var stamps=files.Except(pending).ToDictionary(f=>f.Path,f=>File.GetLastWriteTimeUtc(YandexBundleSource.LocalPath(root,f.Path)));Console.WriteLine(BundleDownloadForm.AlternativeMessage(BundleCloud.Yandex,pending.Count));source.Scan(BundleCloud.Google,token,Console.WriteLine,pending);foreach(var f in pending){if(!source.Contains(BundleCloud.Google,f))throw new Exception("Google has no verified mirror: "+f.Path);long received=0;source.Transfer(BundleCloud.Google).Download(f,root,null,x=>{},token,x=>received+=x,Console.WriteLine);if(!BundlePublication.Matches(root,f,token))throw new Exception("Google hash mismatch");Console.WriteLine("GOOGLE VERIFIED size="+f.Size+" network="+received+" "+f.Path);}
foreach(var f in files){if(!BundlePublication.Matches(root,f,token))throw new Exception("Final mismatch "+f.Path);if(stamps.ContainsKey(f.Path)&&File.GetLastWriteTimeUtc(YandexBundleSource.LocalPath(root,f.Path))!=stamps[f.Path])throw new Exception("Completed file touched "+f.Path);}Console.WriteLine("PASS FINAL files="+files.Count+" bytes="+files.Sum(f=>f.Size)+" YandexFailures="+errors.Count+" simulated="+simulated+". No files executed. UI offer text verified, acceptance simulated by harness.");}
}}
